    ('73135422-d7e1-36be-a102-fe31a9bff7cd', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'SITUATION', $aimong$수업 시간에 AI가 "번역 앱은 어떤 문장도 절대 틀리지 않는다"라고 말했어요. 가장 알맞은 대답은 무엇일까요?$aimong$, $aimong$["근거가 있는지 다른 자료로 다시 확인해요.","말투가 자신 있으니 그대로 믿어요.","길게 설명했으니 무조건 맞다고 생각해요.","친구가 좋아하면 사실이라고 적어 넣어요."]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
