    ('fc8dfbdd-5af8-34ea-a90b-71c4749d3b73', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'OX', $aimong$인공지능에게 질문할 때는 무엇을 하려는지 먼저 말하면 답을 더 알맞게 받을 수 있어요.$aimong$, NULL, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'LOW', NULL, 'GPT', 'PREGENERATED', 3, 'LOW', 'ACTIVE', TRUE),
    ('4b750342-d2ee-37fb-b0a4-7633103158c7', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'OX', $aimong$질문의 목적을 숨겨도 원하는 답을 언제나 그대로 얻을 수 있어요.$aimong$, NULL, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'LOW', NULL, 'GPT', 'PREGENERATED', 3, 'LOW', 'ACTIVE', TRUE),
