    ('3b55e5a2-6cb6-3db7-9021-bc1acb57aba0', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$수업 시간에 구급 로봇이 한 사람만 먼저 도울 수 있는 상황을 두고 모둠이 토의하고 있어요. 가장 알맞은 대답은 무엇일까요?$aimong$, $aimong$["내 생각만 옳다고 밀어붙여요.","영향을 받는 사람과 이유를 따져 봐요.","어려우니 아무 생각도 하지 않아요.","제일 빨리 고를 수 있는 답만 찾으려 해요."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('39f26bc2-3ca3-3dcc-af93-8c61e9b75a5f', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$실험을 하다가 모둠에서 "친구와 선생님 중 누구를 먼저 도울까" 같은 어려운 질문이 나왔어요. 어떤 생각이 가장 적절할까요?$aimong$, $aimong$["어려운 질문이니 그냥 장난처럼 넘겨요.","한 사람 의견만 바로 정답으로 정해요.","쉽게 답이 나지 않는 이유를 함께 말해 봐요.","누가 영향을 받는지는 생각하지 않아요."]$aimong$::jsonb, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('1aed299c-13d7-3257-8818-37367b8e7b78', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$모둠 토의에서 재난 알림 AI가 우선순위를 정해야 하는 상황을 두고 모둠이 토의하고 있어요. 어떤 설명이 가장 좋을까요?$aimong$, $aimong$["내 생각만 옳다고 밀어붙여요.","어려우니 아무 생각도 하지 않아요.","제일 빨리 고를 수 있는 답만 찾으려 해요.","영향을 받는 사람과 이유를 따져 봐요."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('3204e04b-5359-3ddd-af69-649b380635f9', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$활동 중에 모둠에서 "두 지역 중 어디에 먼저 알려야 할까" 같은 어려운 질문이 나왔어요. 어떻게 이해하는 것이 좋을까요?$aimong$, $aimong$["쉽게 답이 나지 않는 이유를 함께 말해 봐요.","어려운 질문이니 그냥 장난처럼 넘겨요.","한 사람 의견만 바로 정답으로 정해요.","누가 영향을 받는지는 생각하지 않아요."]$aimong$::jsonb, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('a27c235e-bd5b-3b4d-8b5c-b5c720b29c74', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$발표를 준비하던 중 배송 로봇이 한 길만 선택할 수 있는 상황을 두고 모둠이 토의하고 있어요. 어떻게 설명하면 좋을까요?$aimong$, $aimong$["내 생각만 옳다고 밀어붙여요.","영향을 받는 사람과 이유를 따져 봐요.","어려우니 아무 생각도 하지 않아요.","제일 빨리 고를 수 있는 답만 찾으려 해요."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('d0416d93-2c75-344f-aeba-8bfe578d08e7', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$결과를 보니 모둠에서 "가까운 사람과 많은 사람 중 누구를 우선할까" 같은 어려운 질문이 나왔어요. 가장 타당한 해석은 무엇일까요?$aimong$, $aimong$["어려운 질문이니 그냥 장난처럼 넘겨요.","한 사람 의견만 바로 정답으로 정해요.","쉽게 답이 나지 않는 이유를 함께 말해 봐요.","누가 영향을 받는지는 생각하지 않아요."]$aimong$::jsonb, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('8c0e6c37-17be-3bab-b5df-02ea27a6f53c', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$다시 해 보니 모둠에서 "개인정보 보호와 편리함 중 무엇을 더 볼까" 같은 어려운 질문이 나왔어요. 어떤 판단이 가장 알맞을까요?$aimong$, $aimong$["쉽게 답이 나지 않는 이유를 함께 말해 봐요.","어려운 질문이니 그냥 장난처럼 넘겨요.","한 사람 의견만 바로 정답으로 정해요.","누가 영향을 받는지는 생각하지 않아요."]$aimong$::jsonb, $aimong$["PROMPT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('2c1485a7-dba3-303a-9c7b-ff782275e7ea', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$교실 대화 중 안전 경고 AI가 제한된 정보로 선택해야 하는 상황을 두고 모둠이 토의하고 있어요. 무엇부터 말해 주면 좋을까요?$aimong$, $aimong$["내 생각만 옳다고 밀어붙여요.","영향을 받는 사람과 이유를 따져 봐요.","어려우니 아무 생각도 하지 않아요.","제일 빨리 고를 수 있는 답만 찾으려 해요."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('e5eb257f-efc6-3509-bcf4-d868a7199d31', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'SITUATION', $aimong$친구가 번역 앱, 식물 인식 앱, 손전등을 모두 AI라고 말했어요. 이때 먼저 던질 질문으로 알맞은 것은 무엇일까요?$aimong$, $aimong$["전기가 들어가는 도구인지 먼저 확인한다.","입력을 보고 판단하는 기능인지 물어본다.","앱 모양이면 모두 AI라고 정한다.","인터넷에 연결되는지만 기준으로 삼는다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('bf58ee8e-74dc-3d7d-a4a5-82814f217606', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'MULTIPLE', $aimong$생활 속 도구가 AI인지 헷갈릴 때 판단 기준으로 알맞은 것은 무엇일까요?$aimong$, $aimong$["가격이 비싸고 화면이 큰지 살핀다.","사람이 자주 쓰는 도구인지 살핀다.","인식·분류·추천 기능이 있는지 살핀다.","충전해서 쓰는 기계인지 살핀다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('fc3babe9-a866-3c0b-808f-96e640a4626a', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'FILL', $aimong$생활 속 AI 구별 문제에서는 도구 이름보다 ____을 먼저 확인해야 해요.$aimong$, $aimong$["데이터로 판단하는 기능","전기를 쓰는 방식","버튼의 개수","도구의 가격"]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('9aa29d17-c6dd-31c5-8fda-621619c8af05', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'SITUATION', $aimong$모둠이 음악 추천 앱, 사진 분류 앱, 계산기를 한 묶음으로 발표하려고 해요. 발표 전에 무엇을 고쳐야 할까요?$aimong$, $aimong$["모두 화면이 있으니 같은 종류라고 설명한다.","가장 자주 쓰는 앱부터 차례대로 소개한다.","이름이 어려운 도구만 AI라고 정한다.","데이터 판단 기능과 계산 기능을 나눈다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('cc3f09f3-4b23-347c-b4b3-b928737985ab', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'MULTIPLE', $aimong$생활 속 AI 구별에서 답이 헷갈릴 때 가장 적절한 풀이 과정은 무엇일까요?$aimong$, $aimong$["입력과 결과에서 판단 기능의 근거를 찾는다.","도구 이름에 AI가 들어가는지 먼저 찾는다.","친구가 고른 답을 기준으로 근거를 맞춘다.","전기를 쓰는지 확인하고 바로 답을 정한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0b618539-b0d6-3c21-aab4-db773ba6051e', '86157cba-318c-3d6c-ab8a-580b1323ff7c', NULL, 'OX', $aimong$생활 속 도구가 AI인지 볼 때는 이름보다 데이터를 이용해 판단하는 기능을 확인해야 한다.$aimong$, NULL, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch3.1 pp.83-96; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0592c39a-7088-3e87-9965-ca474b77fddc', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'SITUATION', $aimong$계산기는 같은 식에 같은 답을 내고, 추천 앱은 사용 기록에 따라 결과가 달라졌어요. 먼저 확인할 점은 무엇일까요?$aimong$, $aimong$["둘 다 빠르게 결과를 내면 같은 AI라고 본다.","숫자가 들어가면 모두 계산기라고 본다.","정해진 규칙 계산인지, 데이터로 배운 판단인지 비교한다.","앱으로 실행되면 모두 학습한다고 본다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('460b4dc0-3b89-3832-9eb2-c17223d09516', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'MULTIPLE', $aimong$AI와 계산기를 구별할 때 가장 도움이 되는 기준은 무엇일까요?$aimong$, $aimong$["계산 결과가 빠르면 AI로 본다.","숫자를 많이 다루면 AI로 본다.","화면 구성이 복잡하면 AI로 본다.","규칙 실행인지 데이터 학습인지 비교한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('4101c2e7-df75-36e8-aadd-3dbba30f4e89', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'FILL', $aimong$AI와 계산기 구별에서는 같은 입력에 같은 규칙만 쓰는지, 아니면 ____을 하는지 살펴야 해요.$aimong$, $aimong$["버튼을 많이 누르기","데이터를 바탕으로 판단","화면을 밝게 보이기","계산식을 크게 쓰기"]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('d00aa983-a767-3592-88ca-fe5910be84ed', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'SITUATION', $aimong$모둠이 계산기, 자동 추천 앱, 날씨 알림을 모두 같은 방식의 도구라고 발표하려 해요. 무엇을 다시 확인해야 할까요?$aimong$, $aimong$["규칙 도구와 데이터 학습 도구를 나눈다.","모두 앱이면 같은 방식이라고 발표한다.","결과가 빠른 순서대로만 정리한다.","숫자나 알림이 있으면 모두 계산기라고 말한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('72834af3-5554-3b40-ab30-7d7b90ff44db', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'MULTIPLE', $aimong$규칙 실행과 학습한 판단을 설명하려면 어떤 순서가 가장 알맞을까요?$aimong$, $aimong$["결과가 빠른 도구를 먼저 AI로 표시한다.","같은 입력의 결과와 데이터 영향을 비교한다.","화면이 있는지 확인하고 바로 답을 고른다.","친구가 익숙한 도구부터 AI라고 정한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('6a4871f7-f7d4-302d-9c68-58d48329ad3f', '47a13864-b7fc-3a8c-ac89-27ae8f5366a7', NULL, 'OX', $aimong$숫자를 빠르게 계산하는 도구는 모두 데이터로 배운 AI라고 볼 수 있다.$aimong$, NULL, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.39-50; Ch3.2 pp.97-103; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('a3d17fcf-af0e-3e2a-b209-5781d3d6106f', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'SITUATION', $aimong$한 모둠은 빨간 사과 사진만 모아 과일을 알아보는 AI를 만들겠다고 했어요. 먼저 확인할 점은 무엇일까요?$aimong$, $aimong$["사진 수만 많으면 색이 같아도 충분하다고 본다.","정답 이름표가 없어도 AI가 알아서 배운다고 본다.","첫 사진을 잘 맞히면 모든 과일도 맞힌다고 본다.","학습 데이터가 한 종류에 치우치지 않았는지 확인한다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('85006a22-7872-3a2d-a7e1-8f115c494db5', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'MULTIPLE', $aimong$AI 학습 데이터의 품질을 볼 때 가장 중요한 기준은 무엇일까요?$aimong$, $aimong$["자료가 다양하고 이름표가 정확한지 함께 본다.","자료가 한 종류라도 개수만 많으면 충분하다.","이름표 없이 사진만 많으면 더 정확하다.","처음 맞힌 결과만 보고 학습이 끝났다고 본다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('f3c5ac7e-d0a6-3948-a5f1-e7510e4f92fa', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'FILL', $aimong$AI가 새 사진도 잘 구별하려면 자료의 수뿐 아니라 ____을 확인해야 해요.$aimong$, $aimong$["사진 파일 이름","화면 밝기","데이터의 다양성","친구가 좋아하는 색"]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('2a48e45b-cb5c-38eb-937d-0f57d8682878', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'SITUATION', $aimong$친구들이 이름표가 빠진 사진과 한 종류 사진만으로 학습 결과를 설명하려고 해요. 무엇을 보완해야 할까요?$aimong$, $aimong$["사진을 더 흐리게 만들어 어렵게 만든다.","다양한 예시와 정확한 이름표를 더해 다시 학습해 본다.","가장 잘 맞힌 사진만 남겨 결과를 발표한다.","이름표는 빼고 사진 개수만 늘린다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('92661225-7b4e-3a6e-b25d-f220bbbea2ac', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'MULTIPLE', $aimong$AI 학습 데이터 판단에서 답이 헷갈릴 때 무엇을 먼저 봐야 할까요?$aimong$, $aimong$["사진이 예쁘고 선명한지만 본다.","가장 많이 나온 색을 정답 기준으로 삼는다.","자료의 다양성과 이름표 정확성을 확인한다.","처음 결과가 맞으면 검사를 끝낸다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('694c509e-0440-3d1a-aedf-e967b39925ac', '2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', NULL, 'OX', $aimong$AI가 데이터를 보고 배울 때는 자료가 한쪽으로 치우치면 결과도 치우칠 수 있다.$aimong$, NULL, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.34-38; Ch3.2 pp.97-103; Ch3.4 pp.119-134$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('aa687275-c938-31b9-8edc-10a534258186', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'SITUATION', $aimong$마스크를 쓴 얼굴과 어두운 사진에서 인식 결과가 서로 다르게 나왔어요. 먼저 확인할 점은 무엇일까요?$aimong$, $aimong$["조명, 각도, 가림처럼 인식 조건이 달라졌는지 본다.","한 번 맞힌 결과가 있으니 항상 정확하다고 본다.","사진 파일 이름이 긴지 먼저 확인한다.","앱이 유명하면 틀릴 수 없다고 본다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('14d1d899-36f0-3fc3-a116-e9178d6aa1c4', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'MULTIPLE', $aimong$딥러닝 인식 결과를 판단할 때 필요한 기준은 무엇일까요?$aimong$, $aimong$["가장 선명한 사진 하나만 보고 판단한다.","맞힌 예와 틀린 예의 조건 차이를 비교한다.","앱 이름이 어려우면 정확하다고 본다.","결과가 빠르면 한계가 없다고 본다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('a5e430b2-366d-3eda-b201-9b949d416589', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'FILL', $aimong$인식 AI를 살필 때는 정답률만 보지 말고 ____를 함께 확인해야 해요.$aimong$, $aimong$["앱 아이콘 색","파일 저장 위치","친구가 좋아하는 사진","인식 조건과 한계"]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('89ff9ed1-8a08-3987-9f6d-2574066b9ed6', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'SITUATION', $aimong$모둠이 사진 한 장에서 맞힌 결과만 보고 인식 AI가 완벽하다고 말하려 해요. 무엇을 더 해야 할까요?$aimong$, $aimong$["맞힌 사진만 크게 보여 주고 끝낸다.","틀린 사례는 발표에서 빼고 설명한다.","다른 조명과 각도에서도 맞히는지 시험한다.","앱 이름을 더 어렵게 바꾸어 소개한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('eff823ac-e378-3e23-aa4a-7426d9e6d58d', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'MULTIPLE', $aimong$인식 조건과 한계를 판단해야 할 때 가장 적절한 풀이 과정은 무엇일까요?$aimong$, $aimong$["처음 떠오른 답을 고르고 근거는 나중에 맞춘다.","정답률 숫자 하나만 보고 결론을 낸다.","앱 이름이 어려운지 먼저 확인한다.","입력 조건과 맞힌 경우, 틀린 경우를 비교한다."]$aimong$::jsonb, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('fd1bf5e8-1c03-3297-8e2c-261b1322d868', 'c95f477c-ba0b-3613-a0a3-59c6fbb375ce', NULL, 'OX', $aimong$한 번 정확히 맞힌 인식 AI는 조명이나 각도가 달라도 항상 같은 답을 낸다.$aimong$, NULL, $aimong$["FACT","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch2.3 pp.61-80; Ch2.1 pp.28-29$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('9996867c-cce6-3ad4-8c57-ba5940587355', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'SITUATION', $aimong$AI가 자신 있게 설명했지만 날짜와 출처가 서로 맞지 않는 답을 냈어요. 먼저 해야 할 일은 무엇일까요?$aimong$, $aimong$["자신 있게 말했으니 그대로 믿는다.","말투보다 확인 가능한 근거와 날짜가 맞는지 살핀다.","문장이 길면 근거가 충분하다고 본다.","친구가 먼저 봤다면 사실 확인을 생략한다."]$aimong$::jsonb, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('eed003d2-b03a-30d1-a5dd-8d2887320e80', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'MULTIPLE', $aimong$AI 답이 맞는지 판단할 때 가장 중요한 기준은 무엇일까요?$aimong$, $aimong$["말투가 친절하면 사실이라고 본다.","답이 길수록 더 정확하다고 본다.","주장에 맞는 근거를 다른 자료로 확인한다.","AI가 확신하면 확인하지 않아도 된다."]$aimong$::jsonb, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('7d40cf90-bc44-3d6e-b227-e97ea6391116', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'FILL', $aimong$AI 답을 그대로 믿기 전에 주장과 맞는 ____를 찾아야 해요.$aimong$, $aimong$["근거","글자 수 세기","화면 색 고르기","가장 빠른 답 선택"]$aimong$::jsonb, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('c2ea81e6-97f6-3ac6-8df5-8e6e9a9f3010', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'SITUATION', $aimong$친구가 AI 답의 말투가 자연스럽다며 바로 발표 자료에 넣으려 해요. 무엇을 권해야 할까요?$aimong$, $aimong$["자연스러운 문장은 모두 사실이라고 말한다.","발표 시간이 없으면 확인을 생략하자고 한다.","AI가 쓴 문장은 친구 의견보다 항상 낫다고 한다.","핵심 주장마다 출처와 근거가 맞는지 먼저 확인하자고 한다."]$aimong$::jsonb, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('2396ab07-c58e-33a8-a951-dc890a703720', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'MULTIPLE', $aimong$AI 오류 확인에서 가장 적절한 사고 과정은 무엇일까요?$aimong$, $aimong$["주장, 날짜, 출처를 나누어 비교한다.","가장 자연스러운 문장을 먼저 고른다.","AI가 먼저 낸 답을 끝까지 유지한다.","친구가 좋아하는 표현을 사실로 정한다."]$aimong$::jsonb, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('396254f6-a63d-3cb6-a584-d3dbd1666bba', '1c16001f-ca97-3b9d-a3b3-bed7f2661350', NULL, 'OX', $aimong$AI 답이 자연스럽게 보여도 사실인지 확인할 근거를 따로 찾아야 한다.$aimong$, NULL, $aimong$["VERIFICATION","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.2 pp.41-43; Ch4.2 p.167; D0qG389 STEP 1$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('f2ad2db5-a6e3-38b7-9ce6-b99a0407c6c8', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'SITUATION', $aimong$친구가 “글 써 줘”라고만 입력했더니 원하는 글과 다른 답이 나왔어요. 무엇을 보완해야 할까요?$aimong$, $aimong$["조건을 빼고 더 짧게만 묻는다.","멋진 글이라고만 반복해서 요청한다.","읽는 사람과 쓰임을 함께 적는다.","AI가 알아서 목적을 정하게 둔다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('7aa11dbe-2568-3144-aed8-f7cb13da1e01', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'MULTIPLE', $aimong$좋은 질문에서 목적을 드러내는 방법으로 알맞은 것은 무엇일까요?$aimong$, $aimong$["조건을 많이 넣되 목적은 숨긴다.","예쁜 말투만 요청하고 쓰임은 빼 둔다.","가장 긴 답을 달라고만 한다.","누구에게, 왜, 어떤 결과물이 필요한지 말한다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0d38f95d-23f6-33b5-a2e8-5490ab9a846c', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'FILL', $aimong$AI에게 질문할 때는 결과물의 형식뿐 아니라 ____을 분명히 해야 해요.$aimong$, $aimong$["글자 색","목적과 상황","친구의 기분","앱의 이름"]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('cc0eb709-fbc2-3276-9f6c-6637875d8184', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'SITUATION', $aimong$모둠이 발표 대본을 부탁하면서 대상과 발표 시간을 빼고 질문하려 해요. 무엇을 넣어야 할까요?$aimong$, $aimong$["누가 들을지와 발표 시간이 어느 정도인지 함께 적는다.","더 멋진 표현을 아무거나 많이 달라고 한다.","AI가 알아서 청중과 시간을 정하게 한다.","발표 주제만 빼고 형식부터 정한다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('94e71160-9b89-3c23-b537-30b39ba4f125', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'MULTIPLE', $aimong$목적이 보이는 질문을 만들 때 가장 적절한 순서는 무엇일까요?$aimong$, $aimong$["먼저 긴 답을 받고 나중에 목적을 맞춘다.","상황, 대상, 원하는 결과물을 함께 적는다.","AI가 준 첫 문장을 그대로 발표한다.","조건을 많이 넣되 누구에게 쓸지는 숨긴다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('751c5af6-a5b5-3ff6-9cde-88e6133f04c6', '2d1960e8-985d-3402-b123-986565bfa3e9', NULL, 'OX', $aimong$AI에게 묻는 질문은 짧을수록 항상 원하는 답을 더 정확히 얻는다.$aimong$, NULL, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2; AImong v1.4 TYPE 2/4 prompt examples$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0d4f5982-236f-36a4-85b2-f85753db5c15', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'SITUATION', $aimong$AI가 너무 긴 답을 내서 친구가 초등학생용 안내문으로 다시 바꾸고 싶어 해요. 어떤 조건이 필요할까요?$aimong$, $aimong$["무조건 자세히만 써 달라고 한다.","대상은 빼고 글자 수만 줄이라고 한다.","어려운 낱말을 더 많이 넣어 달라고 한다.","읽는 사람, 길이, 안내문 형식을 함께 말한다."]$aimong$::jsonb, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('204ecf39-acc1-377a-9485-5a525924c3e7', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'MULTIPLE', $aimong$구체적인 조건 쓰기에서 좋은 기준은 무엇일까요?$aimong$, $aimong$["대상, 분량, 형식, 제외할 내용을 분명히 적는다.","조건을 많이 넣되 서로 모순되게 쓴다.","형식만 말하고 읽는 사람은 빼 둔다.","AI가 알아서 중요한 조건을 고르게 한다."]$aimong$::jsonb, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('86e282a2-dd34-31b8-92d0-78968c29010e', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'FILL', $aimong$좋은 질문은 대상, 길이, 말투처럼 결과를 좁혀 주는 ____을 담아야 해요.$aimong$, $aimong$["앱의 색깔","친구의 별명","구체적인 조건","가장 빠른 버튼"]$aimong$::jsonb, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('2e30899a-031b-37ce-b617-befe6b811294', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'SITUATION', $aimong$모둠이 카드뉴스 문구를 부탁하면서 길이와 말투 조건을 빼고 질문하려 해요. 무엇을 보완해야 할까요?$aimong$, $aimong$["카드뉴스라는 말만 넣고 나머지는 맡긴다.","문구 수, 길이, 말투 조건을 함께 넣는다.","글을 최대한 길게 써 달라고 한다.","어려운 전문어를 많이 넣어 달라고 한다."]$aimong$::jsonb, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('725c3d57-4f92-331e-9589-a4de42e6bec3', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'MULTIPLE', $aimong$조건이 구체적인 질문을 만들 때 가장 적절한 과정은 무엇일까요?$aimong$, $aimong$["조건을 많이 넣고 서로 맞는지는 보지 않는다.","결과를 받은 뒤에만 대상을 정한다.","대상과 목적을 정한 뒤 분량, 형식, 말투 조건을 맞춘다.","AI가 준 첫 답을 조건 확인 없이 쓴다."]$aimong$::jsonb, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('15088ff0-cf43-36a2-b846-503f23134a52', '9aba288d-c43f-3cbb-8ebb-622812c2a9a0', NULL, 'OX', $aimong$좋은 질문에는 대상, 길이, 형식처럼 결과를 좁혀 주는 조건이 들어가면 좋다.$aimong$, NULL, $aimong$["PROMPTING","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.4-3.5 pp.119-154; D0qG389 STEP 2; AImong v1.4$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0e1a8126-6ec3-3740-9262-1ba78890128e', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'SITUATION', $aimong$AI 활동에 친구 얼굴, 이름, 집 근처 사진을 그대로 올리자는 의견이 나왔어요. 먼저 해야 할 일은 무엇일까요?$aimong$, $aimong$["얼굴, 이름, 위치 정보를 빼거나 가린다.","이름만 지우면 얼굴과 위치는 그대로 둔다.","학습 활동이면 허락 없이 올려도 된다고 본다.","사진이 선명할수록 무조건 좋은 자료라고 본다."]$aimong$::jsonb, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('cbd47175-fac5-3269-b712-e8b14ad53834', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'MULTIPLE', $aimong$개인정보를 지키며 AI 자료를 쓸 때 알맞은 기준은 무엇일까요?$aimong$, $aimong$["친구 이름만 빼면 모든 정보가 안전하다고 본다.","꼭 필요한 정보만 쓰고 민감한 정보는 가리거나 빼 둔다.","허락을 한 번 받으면 어떤 자료든 계속 쓴다.","자료가 많을수록 개인정보 걱정은 줄어든다고 본다."]$aimong$::jsonb, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('fd455efb-b821-3ea0-9f88-95b49775bec2', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'FILL', $aimong$개인정보 보호를 더 정확히 하려면 먼저 상황을 읽고 ____를 기준으로 비교해야 해요.$aimong$, $aimong$["화면의 색과 모양","자료의 재미","친구가 고른 번호","민감정보 최소화"]$aimong$::jsonb, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('bcdf4f38-66e0-3ea8-81ed-1ecc4e11073d', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'SITUATION', $aimong$모둠이 생체정보가 들어간 사진을 예시 자료로 쓰기 전에 방법을 정하려 해요. 무엇을 확인해야 할까요?$aimong$, $aimong$["사진이 잘 나왔으면 허락을 생략한다.","이름표만 지우고 얼굴은 그대로 둔다.","허락 여부와 꼭 필요한 정보인지 먼저 확인한다.","친구가 보내 준 자료라면 모두 써도 된다고 본다."]$aimong$::jsonb, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('b9c8cfe6-ec6b-3621-a4d3-9d81708b430c', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'MULTIPLE', $aimong$민감정보 최소화를 판단해야 할 때 가장 적절한 풀이 과정은 무엇일까요?$aimong$, $aimong$["이름만 지우고 나머지는 모두 사용한다.","자료가 많으면 개인정보 문제는 없다고 본다.","친구가 괜찮다고 말한 듯하면 확인을 끝낸다.","알아볼 수 있는 정보는 필요한 만큼만 남기고 나머지는 가린다."]$aimong$::jsonb, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('bca29e0a-ccab-32fe-9706-0d48a4d9e6ab', '46eb38b5-04d9-3ddc-ba12-aa3281d388b7', NULL, 'OX', $aimong$학습 활동에 쓰는 자료라면 친구 사진과 위치 정보는 허락 없이 올려도 된다.$aimong$, NULL, $aimong$["PRIVACY","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch2.1 pp.27-29; Ch4.2 pp.163-178; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('c18658ed-7743-34b4-81eb-17458ed1eea8', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'SITUATION', $aimong$모둠이 인터넷 사진을 모아 AI 학습 자료로 쓰려는데 출처와 허락을 적지 않았어요. 무엇을 먼저 확인해야 할까요?$aimong$, $aimong$["검색해서 나온 사진이면 모두 자유롭게 쓴다.","자료의 출처와 사용 허락, 치우친 사례가 있는지 확인한다.","출처만 적으면 허락은 필요 없다고 본다.","사진이 예쁘면 데이터로 쓰기에 충분하다고 본다."]$aimong$::jsonb, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('9b91f2b1-1cc9-3cf4-b974-75d01d4c6aeb', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'MULTIPLE', $aimong$사진·음성·데이터를 바르게 모으는 기준은 무엇일까요?$aimong$, $aimong$["허락만 있으면 자료가 한쪽이어도 괜찮다.","출처가 있으면 개인정보는 확인하지 않는다.","다양성, 저작권, 허락을 함께 점검한다.","자료 수가 많으면 사용 권리는 보지 않아도 된다."]$aimong$::jsonb, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('d709364d-0db9-3c8d-bb5d-9caa74eb2ab2', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'FILL', $aimong$자료를 모을 때는 다양성뿐 아니라 ____를 함께 확인해야 해요.$aimong$, $aimong$["허락과 출처","파일 이름 길이","사진의 유행","친구가 좋아하는 색"]$aimong$::jsonb, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('36032876-8223-30b2-9f50-7f9cea4502b2', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'SITUATION', $aimong$친구들이 한 종류의 목소리만 녹음해 음성 인식 활동을 끝내려 해요. 무엇을 보완해야 할까요?$aimong$, $aimong$["가장 큰 목소리만 여러 번 녹음한다.","녹음한 사람 이름을 모두 공개한다.","허락은 나중에 받고 먼저 공유한다.","여러 소리와 사용 허락을 함께 확인한다."]$aimong$::jsonb, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('94958eeb-c24b-3b28-8f69-b6335e02b95a', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'MULTIPLE', $aimong$데이터를 바르게 모았는지 판단하는 과정으로 알맞은 것은 무엇일까요?$aimong$, $aimong$["자료가 다양하고, 출처와 허락이 분명한지 함께 확인한다.","자료가 많으면 출처 확인을 생략한다.","예쁜 자료만 골라 데이터 품질을 정한다.","친구가 보내 준 자료는 모두 공개해도 된다고 본다."]$aimong$::jsonb, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('ff7e8dec-6c64-3a69-a8f9-8c96b08449a8', '33a42ea3-e794-3cf7-86b3-523053e97e0b', NULL, 'OX', $aimong$사진·음성·데이터를 모을 때는 다양성뿐 아니라 출처와 사용 허락도 확인해야 한다.$aimong$, NULL, $aimong$["DATA","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154; Ch4.2 pp.167-178$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('a4f1726b-fff9-35a7-932c-c63904b31e2f', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'SITUATION', $aimong$챗봇이 원하는 형식으로 답하지 않았지만 어떤 질문에서 실패했는지 기록하지 않았어요. 무엇을 해야 할까요?$aimong$, $aimong$["성공한 답만 남기고 실패는 지운다.","한 번 실패했으니 도구를 바로 포기한다.","실패한 입력과 결과를 기록해 다시 시험한다.","질문을 바꿔도 기록은 하지 않는다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('9bf72a68-6320-3470-8ef0-35e0bc3d2a69', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'MULTIPLE', $aimong$AI 도구를 실험하고 고칠 때 좋은 기준은 무엇일까요?$aimong$, $aimong$["처음 나온 답을 기준으로 모든 평가를 끝낸다.","마음에 드는 결과만 골라 성공이라고 한다.","조건을 바꾸되 무엇을 바꿨는지는 적지 않는다.","결과를 비교해 원인을 찾고 질문이나 자료를 수정한다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('4c520d1a-937b-32ae-8f8c-41dc815a5d6c', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'FILL', $aimong$AI 도구를 개선하려면 한 번의 결과보다 ____를 보고 수정해야 해요.$aimong$, $aimong$["앱 아이콘 모양","테스트 결과","친구가 고른 색","가장 긴 답"]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('aed9c63f-61b7-3057-a28c-1d3e1dd8d740', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'SITUATION', $aimong$모둠이 한 번 실패한 AI 도구를 바로 포기할지, 조건을 바꿔 볼지 토론해요. 무엇이 더 알맞을까요?$aimong$, $aimong$["실패 원인을 적고 조건을 바꾸어 다시 시험해 본다.","실패한 도구는 이유를 보지 않고 버린다.","성공한 척하고 결과만 예쁘게 꾸민다.","조건은 바꾸지만 이전 결과는 비교하지 않는다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('8eb459cb-60a5-3342-a4ab-7e293fbcb95f', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'MULTIPLE', $aimong$테스트 결과를 설명하려면 어떤 순서가 가장 알맞을까요?$aimong$, $aimong$["마음에 드는 결과만 보여 주고 끝낸다.","처음 조건과 바꾼 조건의 결과를 비교한다.","실패한 이유는 빼고 성공한 척한다.","조건을 바꾼 사실을 기록하지 않는다."]$aimong$::jsonb, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0c0ecd5d-1a5a-3e70-bf2f-3c06673ac9c6', 'bd2cc2f4-b9ed-3512-a772-00548a338ae4', NULL, 'OX', $aimong$AI 도구가 한 번 틀리면 원인을 살피지 않고 바로 사용을 멈추는 것이 가장 좋다.$aimong$, NULL, $aimong$["DATA","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.4 pp.119-134; Ch3.5 pp.135-154$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('68e02214-b064-3f49-b171-3e247a4e399f', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'SITUATION', $aimong$AI가 긴 설명을 줬지만 친구가 뜻을 모른 채 그대로 과제에 붙이려 해요. 무엇을 해야 할까요?$aimong$, $aimong$["문장 순서만 바꾸면 이해하지 않아도 된다.","출처만 적으면 그대로 붙여도 내 답이다.","어려운 낱말을 남겨 두면 더 좋은 답이다.","핵심을 이해한 뒤 자기 말로 다시 정리한다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('f8e4eafc-2ab4-3c0f-8d78-ce23b330da19', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'MULTIPLE', $aimong$AI 도움을 내 답으로 만들 때 좋은 기준은 무엇일까요?$aimong$, $aimong$["모르는 낱말을 확인하고 이해한 내용만 자기 표현으로 쓴다.","문장을 짧게 줄이면 뜻을 몰라도 괜찮다.","AI가 준 표현을 모두 외워서 제출한다.","친구 답과 비슷하게 보이면 이해를 확인하지 않는다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('359c27a2-fcdb-3c0c-b95c-edc80e8bd57f', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'FILL', $aimong$AI 도움을 내 답으로 정리할 때는 예시를 본 뒤 ____를 하고 근거를 말해야 해요.$aimong$, $aimong$["화면의 색과 모양","가장 빠른 결과","자기 말 정리","친구가 고른 번호"]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('6e89565b-0d4c-3cb8-937a-1db8664646b1', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'SITUATION', $aimong$모둠이 AI가 준 힌트를 읽고 발표문을 자기 표현으로 바꿀지 정하려 해요. 무엇이 알맞을까요?$aimong$, $aimong$["AI 문장이 멋지면 그대로 읽는다.","힌트의 뜻을 확인하고 우리 말투와 근거에 맞게 고친다.","뜻을 모르는 낱말도 어려워 보이면 남긴다.","친구가 이해하지 못해도 발표 시간이 짧으면 넘어간다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('e7198d60-95d0-3ed3-a223-ee75fe60760d', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'MULTIPLE', $aimong$AI 도움을 정리하는 가장 적절한 과정은 무엇일까요?$aimong$, $aimong$["문장 끝만 바꾸고 그대로 제출한다.","모르는 낱말이 많을수록 좋은 답이라고 본다.","핵심을 확인하고 자기 표현으로 다시 쓴다.","AI가 준 첫 답을 근거 확인 없이 쓴다."]$aimong$::jsonb, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('6d5255bf-8e77-30eb-beb1-03425bfea023', 'ce49ced9-5114-3824-bcaa-be7b102a5465', NULL, 'OX', $aimong$AI 도움을 받았더라도 이해한 내용을 자기 말로 정리해야 내 답이라고 할 수 있다.$aimong$, NULL, $aimong$["PROMPTING","VERIFICATION"]$aimong$::jsonb, $aimong$KERIS-1 Ch3.1 pp.83-96; Ch3.5 pp.135-154; D0qG389 STEP 2$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('7f0fce03-1052-3193-abfe-f70340b1f4f6', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'SITUATION', $aimong$AI가 “최근 연구에서 증명됐다”고 답했지만 연구 이름과 날짜를 말하지 않았어요. 먼저 해야 할 일은 무엇일까요?$aimong$, $aimong$["주장, 날짜, 출처를 나누어 믿을 만한 자료와 대조한다.","AI가 최근이라고 했으니 바로 사실로 본다.","문장이 자세하면 출처 확인을 생략한다.","같은 말을 두 번 반복하면 근거가 충분하다고 본다."]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('03bf91fd-fa96-3e8d-95ea-c7d199b88051', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'MULTIPLE', $aimong$팩트체크 첫걸음에서 가장 중요한 기준은 무엇일까요?$aimong$, $aimong$["AI가 확신하면 핵심 주장을 그대로 믿는다.","핵심 주장마다 확인할 출처와 날짜를 따로 찾는다.","자료 하나가 보이면 날짜는 보지 않는다.","친구가 많이 들었다고 하면 사실로 본다."]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('4565b538-4658-37a0-bc2a-e2e00d7cfb7d', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'FILL', $aimong$사실 확인을 시작할 때는 먼저 핵심 주장과 확인할 ____를 나누어 보아야 해요.$aimong$, $aimong$["글자 수 세기","화면 꾸미기","친구 의견 맞추기","출처"]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('f98d3f4d-eafa-3f21-a968-eb4d93b160f5', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'SITUATION', $aimong$친구가 AI 답의 문장이 자세하다는 이유로 사실 확인을 끝내려 해요. 무엇을 말해야 할까요?$aimong$, $aimong$["자세하면 모두 사실이니 그대로 쓰자고 한다.","AI가 쓴 문장은 친구 말보다 항상 정확하다고 한다.","자세한 문장도 출처와 날짜가 맞는지 확인해야 한다고 말한다.","출처는 없어도 문장이 길면 충분하다고 한다."]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('2667750d-f761-3ba9-9981-bf4be888419f', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'MULTIPLE', $aimong$팩트체크를 할 때 가장 적절한 순서는 무엇일까요?$aimong$, $aimong$["가장 그럴듯한 문장을 먼저 고른다.","AI 답을 그대로 쓰고 나중에 출처를 붙인다.","친구가 믿는 자료 하나만 확인한다.","주장, 출처, 날짜를 다른 자료와 비교한다."]$aimong$::jsonb, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('d1709122-95df-325a-acce-6eaac82fe0a3', 'e1f12cc1-ab3c-3e16-97d9-1d584890919b', NULL, 'OX', $aimong$AI가 확신 있게 말하면 핵심 주장과 출처 확인을 생략해도 된다.$aimong$, NULL, $aimong$["VERIFICATION","FACT"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.167-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('0c515465-e71c-3b05-bca7-c729459d1935', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'SITUATION', $aimong$두 자료가 같은 주제를 다루지만 작성 기관과 날짜가 서로 달라 결론이 엇갈려요. 무엇을 비교해야 할까요?$aimong$, $aimong$["기관 이름이 더 멋진 자료만 고른다.","누가 언제 어떤 근거로 말했는지 비교한다.","글이 긴 자료는 날짜가 낡아도 믿는다.","내 생각과 맞는 자료만 남긴다."]$aimong$::jsonb, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('ed71e35c-90fb-3568-8363-46a3a97b9798', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'MULTIPLE', $aimong$출처와 근거를 비교할 때 알맞은 기준은 무엇일까요?$aimong$, $aimong$["작성자만 있으면 날짜는 보지 않아도 된다.","댓글이 많으면 근거가 약해도 믿는다.","작성자, 날짜, 기관, 근거가 분명한지 함께 본다.","내가 좋아하는 사이트면 출처 확인을 끝낸다."]$aimong$::jsonb, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('d6de57e7-ed7c-367f-b3b0-af43ed63f63c', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'FILL', $aimong$자료를 비교할 때는 제목보다 ____를 먼저 살펴야 해요.$aimong$, $aimong$["작성자와 근거","글자 크기","사진의 색감","친구가 본 순서"]$aimong$::jsonb, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('009c33d3-8a60-3379-b153-4629aaaec821', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'SITUATION', $aimong$모둠이 블로그 글과 기관 자료 중 어느 쪽을 더 믿을지 정하려 해요. 무엇을 확인해야 할까요?$aimong$, $aimong$["사진이 많은 글을 무조건 더 믿는다.","먼저 찾은 자료를 그대로 정답으로 삼는다.","제목이 강한 자료만 남긴다.","작성자, 날짜, 근거가 분명한 자료를 비교한다."]$aimong$::jsonb, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('7b954c66-bbd0-3f8f-8d97-2e42aa7829d6', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'MULTIPLE', $aimong$출처 비교 문제를 풀 때 가장 적절한 과정은 무엇일까요?$aimong$, $aimong$["작성자, 날짜, 기관, 근거를 나누어 비교한다.","내 생각과 맞는 자료만 골라 읽는다.","제목이 짧은 자료를 더 정확하다고 본다.","자료가 많으면 출처는 보지 않아도 된다고 본다."]$aimong$::jsonb, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('83081660-940f-3e22-9b11-71069d03916a', '18e08973-00ce-3f59-9362-b05ad1eb2ca3', NULL, 'OX', $aimong$출처를 볼 때는 글쓴이뿐 아니라 날짜, 기관, 근거가 분명한지도 비교해야 한다.$aimong$, NULL, $aimong$["VERIFICATION","SOURCE"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1-4.2 pp.157-178; D0qG389 STEP 3$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('dd9a8209-adb5-3d4c-8ddd-ad322c3e931f', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'SITUATION', $aimong$모둠이 한 지역 학생 몇 명의 답만 보고 모든 학생의 생각이라고 발표하려 해요. 먼저 확인할 점은 무엇일까요?$aimong$, $aimong$["사례 수가 세 개 이상이면 모두 대표한다고 본다.","내 생각과 같으면 모든 학생도 같다고 본다.","누가 빠졌는지, 한쪽 사례만 모였는지 따져 본다.","AI가 추천한 예시는 항상 공정하다고 본다."]$aimong$::jsonb, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('ebf8a541-70ed-368d-9a81-9b6632fedc9b', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'MULTIPLE', $aimong$편향을 찾을 때 가장 알맞은 기준은 무엇일까요?$aimong$, $aimong$["자료가 많아 보이면 대표성은 확인하지 않는다.","한쪽 의견이 많으면 그쪽이 항상 맞다고 본다.","AI가 골랐으면 치우침이 없다고 본다.","자료에 빠진 집단과 반복되는 관점이 있는지 본다."]$aimong$::jsonb, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('21008d48-b718-3c27-9829-e2dab6d673a8', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'FILL', $aimong$AI 추천이나 조사 결과를 볼 때는 사례 수뿐 아니라 ____을 확인해야 해요.$aimong$, $aimong$["글자 모양","대표성","가장 빠른 답","앱의 이름"]$aimong$::jsonb, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('6b70d0d7-9c71-3580-8540-4ed66364cad4', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'SITUATION', $aimong$AI가 추천한 예시가 비슷한 사람과 상황으로만 채워져 있다는 의견이 나왔어요. 무엇을 해야 할까요?$aimong$, $aimong$["빠진 사람과 상황을 찾아 자료를 더 고르게 모은다.","비슷한 예시가 많으니 더 정확하다고 본다.","추천 결과는 AI가 골랐으니 검토하지 않는다.","처음 나온 예시만 발표에 사용한다."]$aimong$::jsonb, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('a0307850-1b59-39c2-8570-ba1d33b3d777', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'MULTIPLE', $aimong$편향을 찾아보는 가장 적절한 과정은 무엇일까요?$aimong$, $aimong$["가장 많이 보이는 의견을 바로 정답으로 삼는다.","자료가 누구를 포함하고 누구를 빠뜨렸는지 비교한다.","내가 좋아하는 사례만 모아 결론을 낸다.","AI 추천이면 공정하다고 보고 끝낸다."]$aimong$::jsonb, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('1ef66328-2224-39f3-bd67-cd960615062c', 'ca965f02-d5f7-36c0-960c-f463e53951ff', NULL, 'OX', $aimong$사례가 세 개 있으면 어떤 주제든 항상 공정한 결론을 낼 수 있다.$aimong$, NULL, $aimong$["BIAS","DATA"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.2 pp.163-178; Ch4.4 pp.192-224$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('df77375f-4d8c-3f5b-8354-a20b155bed1d', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'SITUATION', $aimong$AI 번역이 편리하다는 발표에 오류와 개인정보 걱정은 빠져 있었어요. 무엇을 보완해야 할까요?$aimong$, $aimong$["장점이 크면 단점은 발표에서 빼도 된다고 본다.","위험이 있으면 모든 AI 사용을 금지한다고 결론낸다.","내가 편리하면 다른 사람 영향은 보지 않는다.","편리한 점과 조심할 점을 함께 비교한다."]$aimong$::jsonb, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('6169e247-7c7a-322d-a5af-a201e81842e0', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'MULTIPLE', $aimong$AI의 양면성을 판단할 때 알맞은 기준은 무엇일까요?$aimong$, $aimong$["도움이 되는 점과 조심할 점을 같은 기준으로 나눈다.","편리함 하나가 있으면 모든 문제가 해결된다고 본다.","문제가 하나 있으면 장점은 전혀 없다고 본다.","친구가 좋아하면 사회적 영향은 보지 않는다."]$aimong$::jsonb, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('43028b6d-af4d-30a9-aa88-ad416f0a8944', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'FILL', $aimong$AI의 영향을 생각할 때는 장점만 보지 말고 ____을 함께 살펴야 해요.$aimong$, $aimong$["앱 이름","글자 수","양면성","가장 빠른 결과"]$aimong$::jsonb, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('9d0c5bc7-1859-3ac4-a930-a70af748e872', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'SITUATION', $aimong$친구들이 AI가 편리하다는 장점만 모아 토론 자료를 만들려 해요. 무엇을 더 넣어야 할까요?$aimong$, $aimong$["장점이 충분하면 반대 의견은 빼 둔다.","오류, 개인정보, 책임처럼 조심할 점도 함께 넣는다.","가장 멋진 사례만 모아 결론을 낸다.","문제가 생기면 사용자를 탓하면 된다고 쓴다."]$aimong$::jsonb, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('06b71e71-3877-3618-8c7a-a21c5c1e47fd', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'MULTIPLE', $aimong$AI의 양면성을 설명하는 가장 적절한 과정은 무엇일까요?$aimong$, $aimong$["장점 하나를 크게 쓰고 결론을 끝낸다.","위험만 모아 모든 사용을 나쁘다고 한다.","도움, 위험, 필요한 약속을 나누어 비교한다.","내가 편한지만 보고 사회적 영향은 뺀다."]$aimong$::jsonb, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('e98d6bde-1635-33fd-bda7-fec9fc2785ff', '2e51ec66-f05d-37fe-a76a-2fd8fe62662e', NULL, 'OX', $aimong$AI의 영향을 판단할 때는 편리한 점과 조심해야 할 점을 함께 살펴야 한다.$aimong$, NULL, $aimong$["ETHICS","SAFETY"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.1 pp.157-162$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('bf95751f-6c27-3eeb-8de7-4ed7cb726e9a', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$AI가 정한 순서 때문에 어떤 친구는 도움을 빨리 받고 다른 친구는 오래 기다려야 해요. 무엇을 먼저 따져야 할까요?$aimong$, $aimong$["누가 이익이나 불편을 겪는지 기준을 세워 비교한다.","전체 평균 시간이 줄면 누구에게나 공정하다고 본다.","AI가 계산했으니 결과는 항상 공정하다고 본다.","목소리가 큰 친구 의견을 기준으로 정한다."]$aimong$::jsonb, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('5d32f7b0-5598-32b8-873a-77a359975c20', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'MULTIPLE', $aimong$딜레마에서 공정한 선택을 하려면 어떤 기준이 필요할까요?$aimong$, $aimong$["가장 빠른 해결만 고르면 모두에게 공정하다고 본다.","관련된 사람들의 입장과 공정한 기준을 함께 따진다.","AI 추천이면 책임을 따질 필요가 없다고 본다.","내가 손해 보지 않는 선택을 공정하다고 본다."]$aimong$::jsonb, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('5b227a74-b0db-3d27-826d-d5e4259edcbe', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'FILL', $aimong$AI 결정이 공정한지 보려면 결과뿐 아니라 ____을 확인해야 해요.$aimong$, $aimong$["버튼 위치","앱의 속도","친구가 먼저 말한 의견","공정성 기준"]$aimong$::jsonb, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('32bd458d-0f4d-3793-ab7c-ef0eb5d12f59', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'SITUATION', $aimong$모둠이 AI 추천 결과를 그대로 따를지, 사람에게 미치는 영향을 따져 볼지 정하려 해요. 무엇이 알맞을까요?$aimong$, $aimong$["AI가 추천했으니 사람의 영향은 보지 않는다.","가장 빠른 결과만 고르고 이유는 생략한다.","추천 결과가 누구에게 어떤 영향을 주는지 함께 살핀다.","친한 친구에게 유리한 결과를 공정하다고 본다."]$aimong$::jsonb, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('058028a3-11b4-3ed8-a8fe-c6ba7515f083', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'MULTIPLE', $aimong$공정성 기준을 판단해야 할 때 가장 적절한 풀이 과정은 무엇일까요?$aimong$, $aimong$["내가 편한 결과를 먼저 고르고 근거를 맞춘다.","AI가 계산한 결과라면 검토하지 않는다.","목소리가 큰 사람에게 유리한 기준을 따른다.","관련된 사람과 기준 적용을 비교한다."]$aimong$::jsonb, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE),
    ('3b2a9694-8c0d-3f8d-80f7-3dfee2e024aa', '5f01b2ce-caf2-3045-8aac-59f35fa5bc55', NULL, 'OX', $aimong$AI 결정은 계산으로 나온 결과라서 사람에게 미치는 영향까지 볼 필요가 없다.$aimong$, NULL, $aimong$["ETHICS","FAIRNESS"]$aimong$::jsonb, $aimong$KERIS-1 Ch4.3 pp.179-191$aimong$, 'HIGH', NULL, 'GPT', 'PREGENERATED', 6, 'HIGH', 'ACTIVE', TRUE)
INSERT INTO private.question_answer_keys (question_id, answer_payload, explanation) VALUES
    ('ae8d7e0d-89d9-3d3d-aa4b-b42e59aec305', $aimong$true$aimong$::jsonb, $aimong$번역 앱, 카메라 앱, 인공지능 스피커처럼 생활 속 도구에도 인공지능이 쓰일 수 있어요. 다음 문제에서도 인공지능의 특징을 떠올려 보세요.$aimong$),
    ('0031da4f-c47a-3cad-b07a-1fd5862c9782', $aimong$false$aimong$::jsonb, $aimong$빠른 계산만 하는 도구와, 데이터를 보고 분류하거나 추천하는 인공지능은 같지 않아요. 비슷한 장면에서도 인공지능의 특징을 먼저 살펴보세요.$aimong$),
    ('86fcf72b-bbb4-3287-a9d8-c52062064cf7', $aimong$1$aimong$::jsonb, $aimong$생활 속 인공지능은 보거나 듣거나 비교해 판단하는 기능을 갖는 경우가 많아요. 고민될 때는 인공지능의 특징을 다시 생각해 보세요.$aimong$),
    ('c25fe073-0389-3ba9-9954-38ce388e8805', $aimong$3$aimong$::jsonb, $aimong$도구의 모양보다 어떤 일을 하는지 묻는 질문이 더 중요해요. 선택할 때는 인공지능의 특징을 먼저 따져 보세요.$aimong$),
    ('6feffb52-8d58-325d-93c6-8c14764a4fdb', $aimong$[1]$aimong$::jsonb, $aimong$인공지능인지 판단할 때는 어떤 기능을 수행하는지 보는 습관이 중요해요. 서로 살필 때는 인공지능의 특징을 먼저 보세요.$aimong$),
    ('fb67594d-a460-3fd6-8867-31fda2ba710a', $aimong$false$aimong$::jsonb, $aimong$전기를 쓴다는 사실만으로는 AI인지 알 수 없어요. 데이터를 보고 인식·분류·추천처럼 판단하는 기능이 있는지 확인해야 해요.$aimong$),
    ('1d56b048-e383-3b0c-8191-2a7f4d0163bc', $aimong$true$aimong$::jsonb, $aimong$전기를 쓴다는 사실만으로는 AI인지 알 수 없어요. 데이터를 보고 인식·분류·추천처럼 판단하는 기능이 있는지 확인해야 해요.$aimong$),
    ('54252005-07fd-3e4b-a1c4-404908c372ae', $aimong$2$aimong$::jsonb, $aimong$생활 속 인공지능은 보거나 듣거나 비교해 판단하는 기능을 갖는 경우가 많아요. 비슷한 상황에서는 인공지능의 특징을 다시 생각해 보세요.$aimong$),
    ('a2d85886-ca7a-3a77-a5d2-b3e010e1b700', $aimong$0$aimong$::jsonb, $aimong$도구의 모양보다 어떤 일을 하는지 묻는 질문이 더 중요해요. 문항을 풀 때는 인공지능의 특징을 먼저 따져 보세요.$aimong$),
